      throw new Error("CSV requires a service");
    }
    console.log(csv(result[service], service));
  } else {
    console.log(JSON.stringify(result, null, 2));
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
