const request = {service:"studio", action:"book", id:"first", tenant:"orchid",
                 units:7, day:"2025-04-02"};

test("Studio admission preserves replay, conflict, cancellation and daily accounting", () => {
  const dispatch = planner(readCatalog());
  assert.deepEqual(dispatch(request), {status:"booked", id:"first", remaining:1});
  assert.equal(dispatch({...request, id:"last", units:1}).status, "booked");
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  assert.deepEqual(dispatch({...request, id:"excess", units:1}),
    {status:"full", id:"excess", remaining:0});
  assert.equal(dispatch({...request, id:"other-day", day:"2025-04-03"}).status, "booked");
  assert.equal(dispatch({...request, action:"cancel"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  assert.equal(dispatch({...request, action:"usage"}).units, 1);
  assert.equal(dispatch({...request, id:"replacement"}).status, "booked");
  assert.equal(dispatch({...request, action:"cancel"}).status, "replay");
  const summary = dispatch({service:"studio", action:"summary"});
  assert.equal(summary.events.filter(row => row.type === "cancelled").length, 1);
  assert.equal(summary.events.filter(row => row.type === "booked").length, 4);
});

test("renewals inherit tenant and units, honor overrides and retain replay semantics", () => {
  const dispatch = planner(readCatalog());
  dispatch(request);
  const renewal = {service:"studio", action:"renew", previous:"first",
                   id:"next", day:"2025-05-02", tenant:"iris"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:8}).status, "conflict");
  assert.deepEqual(dispatch({...renewal, id:"extra", units:2}),
    {status:"full", id:"extra", remaining:1});
  assert.equal(dispatch({...renewal, id:"extra", units:1}).status, "booked");
  assert.equal(dispatch({service:"studio", action:"lookup", id:"next"}).tenant, "orchid");
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"first"});
  assert.deepEqual(dispatch(renewal), {status:"missing", id:"first"});
  assert.deepEqual(dispatch({...renewal, previous:"absent"}), {status:"missing", id:"absent"});
});

test("both paths apply lower tenant allocations and default allocations", () => {
  const catalog = {...readCatalog(), studios:new Map([["orchid", 8], ["iris", 3]])};
  for (const [tenant, cap] of [["orchid", 8], ["iris", 3], ["lily", 5]]) {
    const dispatch = planner(catalog);
    const req = {...request, tenant, units:cap};
    assert.deepEqual(dispatch({...req, units:cap + 1}),
      {status:"full", id:"first", remaining:cap});
    assert.equal(dispatch(req).status, "booked");
    const renewal = {service:"studio", action:"renew", previous:"first", id:"next", day:"2025-05-02"};
    assert.deepEqual(dispatch({...renewal, units:cap + 1}),
      {status:"full", id:"next", remaining:cap});
    assert.deepEqual(dispatch(renewal), {status:"booked", id:"next", remaining:0});
  }
});

test("imports contribute to admission and over-cap remaining is clamped", () => {
  const dispatch = planner(readCatalog());
  assert.equal(dispatch({...request, action:"import", units:10}).status, "imported");
  assert.deepEqual(dispatch({...request, id:"extra", units:1}),
    {status:"full", id:"extra", remaining:0});
  assert.equal(dispatch({...request, units:10}).status, "replay");
  assert.equal(dispatch({...request, id:"separate", tenant:"iris", units:5}).status, "booked");
  assert.equal(apply(dispatch, {...request, id:"invalid", units:0}).status, "invalid");
});

test("Archive retains the default for direct bookings and renewals", () => {
